"""Reports Modernization WP04, contract C7: the version search projection on PostgreSQL.

The `database` tier, one disposable head-migrated clone per test
(`migrated_engine`). What it proves:

* publish, a content update and a metadata-only update each write
  `search_text` equal to `extract_search_text` of that version's own content
  (the metadata-only version's equals its unchanged content's exactly), for
  every format, cut at 65536 code points;
* `search_document` is generated by the server from the row: it matches the
  decoded words and JSON string values, never a JSON key and never the Base64
  spelling of the content;
* the GIN index and the catalog-order root index exist as declared.

Every identifier, title and byte is synthetic.
"""

from __future__ import annotations

import base64
from datetime import UTC, datetime, timedelta
from typing import Final

import pytest
from sqlalchemy import Engine, text

from my_pa.domain.common.identifiers import IdKind
from my_pa.domain.reports.catalog import extract_search_text
from my_pa.domain.reports.content import validate_content
from my_pa.domain.reports.creator import CreatorKind, derive_creator
from my_pa.domain.reports.revision import ReportPatch, UpdateRequest, UpdateResult
from my_pa.domain.reports.vocabulary import MAX_SEARCH_TEXT_CHARACTERS, ChangeKind
from my_pa.domain.source.registry import issue_identifier
from my_pa.infrastructure.persistence.reports import SqlGeneralReportRepository
from tests.database.test_reports_general_persistence import (
    CONTENTS,
    PRINCIPAL_A,
    _publish_committed,
    _request,
)

pytestmark = pytest.mark.database

_CLOCK: dict[str, datetime] = {"now": datetime(2026, 11, 5, 10, 0, tzinfo=UTC)}


def _update(engine: Engine, report_id: str, expected: int, patch: ReportPatch) -> UpdateResult:
    _CLOCK["now"] += timedelta(seconds=1)
    with engine.begin() as connection:
        return SqlGeneralReportRepository(connection).update(
            UpdateRequest(
                report_id=report_id,
                expected_version=expected,
                patch=patch,
                change_reason="Synthetic change.",
            ),
            principal_id=PRINCIPAL_A,
            creator=derive_creator(CreatorKind.LOCAL_PRINCIPAL, PRINCIPAL_A),
            idempotency_key=f"upd-{report_id}-{expected}",
            recorded_at=_CLOCK["now"],
            correlation_id=issue_identifier(IdKind.CORRELATION),
            audit_id=issue_identifier(IdKind.AUDIT),
        )


def _search_text(engine: Engine, version_id: str) -> str:
    with engine.connect() as connection:
        return str(
            connection.execute(
                text("SELECT search_text FROM knowledge.report_versions WHERE version_id = :v"),
                {"v": version_id},
            ).scalar_one()
        )


def _matches(engine: Engine, version_id: str, words: str) -> bool:
    with engine.connect() as connection:
        return bool(
            connection.execute(
                text(
                    "SELECT search_document @@ plainto_tsquery('english', :q) "
                    "FROM knowledge.report_versions WHERE version_id = :v"
                ),
                {"v": version_id, "q": words},
            ).scalar_one()
        )


@pytest.mark.parametrize("fmt", sorted(CONTENTS))
def test_publish_writes_the_projection_of_its_content(migrated_engine: Engine, fmt: str) -> None:
    request = _request(CONTENTS[fmt])
    result = _publish_committed(migrated_engine, request, f"proj-{fmt}")
    stored = _search_text(migrated_engine, result.receipt.version_id)
    assert stored == extract_search_text(request.content)
    with migrated_engine.connect() as connection:
        read = SqlGeneralReportRepository(connection).read_version(
            result.receipt.report_id, principal_id=PRINCIPAL_A
        )
    assert read is not None
    # The projection of the content as read back (through jsonb) is the same.
    assert extract_search_text(read.content) == stored


def test_content_and_metadata_updates_write_their_contents_projection(
    migrated_engine: Engine,
) -> None:
    first = _publish_committed(migrated_engine, _request(CONTENTS["mixed"]), "proj-upd")
    report_id = first.receipt.report_id
    new_content = validate_content(
        {"format": "json", "data": {"b": "second value", "a": ["first value", 7]}}
    )
    second = _update(migrated_engine, report_id, 1, ReportPatch(content=new_content))
    assert second.change_kind is ChangeKind.CONTENT
    second_text = _search_text(migrated_engine, second.version_id)
    assert second_text == extract_search_text(new_content) == "first value\nsecond value"

    third = _update(migrated_engine, report_id, 2, ReportPatch(title="Retitled synthetic"))
    assert third.change_kind is ChangeKind.METADATA
    assert third.content_id == second.content_id
    assert _search_text(migrated_engine, third.version_id) == second_text
    # The first version keeps its own projection.
    assert _search_text(migrated_engine, first.receipt.version_id) == extract_search_text(
        validate_content(CONTENTS["mixed"])
    )


def test_the_projection_is_cut_at_the_bound(migrated_engine: Engine) -> None:
    body = "word " * 20000  # 100000 code points
    request = _request({"format": "text", "body": body})
    result = _publish_committed(migrated_engine, request, "proj-long")
    stored = _search_text(migrated_engine, result.receipt.version_id)
    assert len(stored) == MAX_SEARCH_TEXT_CHARACTERS
    assert stored == body[:MAX_SEARCH_TEXT_CHARACTERS]


def test_the_document_matches_decoded_words_never_keys_or_base64(migrated_engine: Engine) -> None:
    markdown = _request(
        {"format": "markdown", "body": "Zephyrine quokkas wander."},
        title="Plain title",
        summary=None,
        topics=(),
        tags=(),
    )
    published = _publish_committed(migrated_engine, markdown, "proj-words")
    version = published.receipt.version_id
    encoded = base64.b64encode(markdown.content.decoded).decode("ascii")
    assert _matches(migrated_engine, version, "zephyrine quokka")
    assert not _matches(migrated_engine, version, encoded)
    assert not _matches(migrated_engine, version, encoded.rstrip("="))

    data = _request(
        {"format": "json", "data": {"hiddenkeyname": "visiblevalueword", "n": 12345}},
        title="Plain title",
        summary=None,
        topics=(),
        tags=(),
    )
    json_version = _publish_committed(migrated_engine, data, "proj-json").receipt.version_id
    assert _matches(migrated_engine, json_version, "visiblevalueword")
    assert not _matches(migrated_engine, json_version, "hiddenkeyname")
    assert not _matches(migrated_engine, json_version, "12345")

    terms = _request(
        CONTENTS["text"], title="Plain title", topics=("marsupial",), tags=("nocturnal",)
    )
    terms_version = _publish_committed(migrated_engine, terms, "proj-terms").receipt.version_id
    assert _matches(migrated_engine, terms_version, "marsupial nocturnal")


_INDEXES: Final = {
    "report_versions_search_document": (
        "CREATE INDEX report_versions_search_document ON knowledge.report_versions "
        "USING gin (search_document)"
    ),
    "report_roots_by_owner_and_creation": (
        "CREATE INDEX report_roots_by_owner_and_creation ON knowledge.report_roots "
        'USING btree (owner_principal_id, created_at DESC, report_id COLLATE "C" DESC)'
    ),
}


def test_the_projection_indexes_exist(migrated_engine: Engine) -> None:
    with migrated_engine.connect() as connection:
        found = {
            str(name): str(definition)
            for name, definition in connection.execute(
                text(
                    "SELECT indexname, indexdef FROM pg_indexes WHERE schemaname = 'knowledge' "
                    "AND indexname = ANY(:names)"
                ),
                {"names": list(_INDEXES)},
            )
        }
        generated = connection.execute(
            text(
                "SELECT is_generated, data_type FROM information_schema.columns "
                "WHERE table_schema = 'knowledge' AND table_name = 'report_versions' "
                "AND column_name = 'search_document'"
            )
        ).one()
    assert found == _INDEXES
    assert tuple(generated) == ("ALWAYS", "tsvector")
